export const parsePath = (string: StringifiedPath, legacy = false) => {
  const result: string[] = [];

  let segment = '';
  for (let i = 0; i < string.length; i++) {
    let char = string.charAt(i);

    if (char === '\\') {
      const nextChar = string.charAt(i + 1);

      if (nextChar === '.') {
        // Escaped dot → literal dot
        segment += '.';
        i++;
        continue;
      }

      if (nextChar === '\\') {
        if (legacy) {
          // Legacy mode: \\ is treated as literal \\
          segment += '\\';
          i++;
          continue;
        } else {
          // New mode: \\\\ → literal \\
          segment += '\\';
          i++;
          continue;
        }
      }

      if (legacy) {
        // Legacy mode: backslash followed by anything else is kept as-is
        segment += char;
        continue;
      } else {
        // New mode: backslash followed by anything else is invalid
        throw new Error(
          `Invalid escape sequence: \\${nextChar}`
        );
      }
    }

    const isEndOfSegment = char === '.';
    if (isEndOfSegment) {
      result.push(segment);
      segment = '';
      continue;
    }

    segment += char;
  }

  if (!legacy && segment.endsWith('\\')) {
    throw new Error('Path must not end with a backslash');
  }

  const lastSegment = segment;
  result.push(lastSegment);

  return result;
};

